// 開啟 /log 時只讀檔尾這麼多位元組，避免大檔一次全部載入；
// 畫面最多保留的筆數，超過時丟棄最舊的；
// 時間欄的顯示格式（本地時間，到毫秒）。
const (
	LOG_TAIL_BYTES  = 256 << 10
	LOG_MAX_ENTRIES = 2000
	LOG_TIME_FORMAT = "15:04:05.000"
)

// 等級標籤的顏色，色碼對齊 WebUI 的 --log-info / --log-debug / --log-warn / --log-error：
// Light 對應 WebUI 淺色主題，Dark 對應深色主題；不在表內的等級用灰色。
var logLevelStyles = map[string]lipgloss.Style{
	"INFO":  lipgloss.NewStyle().Foreground(lipgloss.AdaptiveColor{Light: "#0F172A", Dark: "#ECEEF2"}),
	"DEBUG": lipgloss.NewStyle().Foreground(lipgloss.AdaptiveColor{Light: "#2563EB", Dark: "#4F8CFF"}),
	"WARN":  lipgloss.NewStyle().Foreground(lipgloss.AdaptiveColor{Light: "#6D28D9", Dark: "#B69CFF"}),
	"ERROR": lipgloss.NewStyle().Foreground(lipgloss.AdaptiveColor{Light: "#DC2626", Dark: "#F87171"}),
}

// logfmt 的一組 key=value；value 已去掉引號並還原跳脫字元。
type logAttr struct {
	key   string
	value string
}

// 一筆解析後的 log。
// raw 非空代表該行不是 slog 的 logfmt 格式（例如 panic 堆疊），原樣顯示，其餘欄位不使用。
// time 為格式化後的本地時間；解析失敗時保留原字串。
// attrs 為 level、msg 以外的欄位，順序與原始行相同。
type logEntry struct {
	raw   string
	time  string
	level string
	msg   string
	attrs []logAttr
}

// 監看 goroutine 送回 TUI 主迴圈的新內容。
// target 是發出監看的 popup，用來判斷 popup 是否仍開著；
// reset 為 true 代表檔案被截斷或輪替，畫面需清空後以 lines 重建。
type LogStream struct {
	target *Popup
	lines  []string
	reset  bool
}

// /log popup 的狀態，掛在 Popup.logView 上。
// entries 是已解析的 log（上限 LOG_MAX_ENTRIES）；
// width 是上次排版用的終端機寬度，視窗寬度改變時用來判斷是否需重排；
// follow 只在第一次排版前為 true，確保一開啟就捲到最底。
type logView struct {
	entries []logEntry
	width   int
	follow  bool
}

// /log：開啟唯讀 popup 並啟動 daemon.log 的監看。
// popup 先顯示 loading...，監看 goroutine 讀完檔尾後以 LogStream 填入；
// popup 關閉時（Esc、Enter、返回上一層）由 onClose 取消 ctx，停止監看。
func (t TUI) commandLog() (TUI, tea.Cmd, bool) {
	ctx, cancel := context.WithCancel(t.ctx)
	view := &logView{follow: true}
	popup := &Popup{
		kind:        popupSingleSelect,
		title:       "/log",
		subtitle:    filesystem.DaemonLogPath,
		styledLines: []string{hintStyle.Render("  loading...")},
		readOnly:    true,
		rawLines:    true,
		logView:     view,
		onClose:     cancel,
	}
	t.popup = popup
	// NOTE: 監看在背景執行，結果經 send() 回到主迴圈，不阻塞畫面
	go watchDaemonLog(ctx, popup)
	return t, nil, true
}

// 處理監看送回的新內容：解析後附加到 entries，再重新排版。
func (t TUI) runLogStream(msg LogStream) (TUI, tea.Cmd) {
	p := msg.target
	// NOTE: popup 已關閉或被其他 popup 取代：補呼叫 onClose 停止監看，丟棄這批內容
	if t.popup != p {
		if p.onClose != nil {
			p.onClose()
		}
		return t, nil
	}
	view := p.logView
	if msg.reset {
		view.entries = nil
	}
	for _, line := range msg.lines {
		view.entries = append(view.entries, parseLogLine(line))
	}
	// NOTE: 只保留最新的 LOG_MAX_ENTRIES 筆
	if over := len(view.entries) - LOG_MAX_ENTRIES; over > 0 {
		view.entries = view.entries[over:]
	}
	renderLogView(p, t.width)
	return t, nil
}

// 依目前寬度把 entries 排成 popup 的顯示行（p.options），並決定捲動位置。
// 捲動位置以 p.cursor 表示可見區第一行；停在底部時新內容進來會自動跟到底，
// 使用者往上捲之後則維持原位。
func renderLogView(p *Popup, width int) {
	view := p.logView
	if width < 20 {
		width = 80
	}
	// NOTE: visibleRows 由 view.go 每次繪製時回填；以「重排前」的行數判斷目前是否停在底部
	visible := p.visibleRows
	follow := view.follow || p.cursor >= max(len(p.options)-visible, 0)
	view.width = width

	// NOTE: 沒有內容時在 popup 內顯示空狀態，監看持續進行
	if len(view.entries) == 0 {
		p.options = nil
		p.styledLines = []string{hintStyle.Render("  no daemon log yet  waiting for new lines")}
		return
	}
	p.styledLines = nil

	lines := make([]string, 0, len(view.entries))
	for _, entry := range view.entries {
		// NOTE: 扣掉 popup 邊框與左側 2 格 marker 的寬度
		lines = append(lines, formatLogEntry(entry, width-6)...)
	}
	p.options = lines
	if follow {
		p.cursor = max(len(lines)-visible, 0)
	}
	view.follow = false
}

// 把一筆 log 排成一或多行：
//
//	02:53:27.985 DEBUG skill relevance check session=cli-71876839-7a29-40f9-be
//	                   52-a8bac329f40b skills=24 unrelated=23
//
// 第一行為「時間 等級 訊息 欄位」，超過寬度時直接按寬度切斷，
// 後續行縮排到訊息欄，不會折回第 0 欄；非 logfmt 的行整行換行、不縮排。
func formatLogEntry(entry logEntry, width int) []string {
	if entry.raw != "" {
		return strings.Split(hardWrap(textStyle.Render(entry.raw), max(width, 20)), "\n")
	}

	// NOTE: 等級補到 5 字元寬（DEBUG / ERROR 的長度），讓訊息欄上下對齊
	level := entry.level
	if len(level) < 5 {
		level += strings.Repeat(" ", 5-len(level))
	}
	levelStyle, ok := logLevelStyles[strings.ToUpper(entry.level)]
	if !ok {
		levelStyle = hintStyle
	}
	head := hintStyle.Render(entry.time) + " " + levelStyle.Render(level) + " "
	// NOTE: 縮排寬度用未上色的字串計算，ANSI 色碼不佔顯示寬度
	indent := len(entry.time) + 1 + len(level) + 1

	var body strings.Builder
	body.WriteString(whiteStyle.Render(entry.msg))
	for _, attr := range entry.attrs {
		value := attr.value
		// NOTE: 含空白、引號或為空字串的值重新加上引號，避免與下一個欄位混在一起
		if strings.ContainsAny(value, " \t\"") || value == "" {
			value = strconv.Quote(value)
		}
		body.WriteByte(' ')
		body.WriteString(hintStyle.Render(attr.key + "="))
		body.WriteString(textStyle.Render(value))
	}

	lines := strings.Split(hardWrap(body.String(), max(width-indent, 20)), "\n")
	pad := strings.Repeat(" ", indent)
	for i, line := range lines {
		if i == 0 {
			lines[i] = head + line
			continue
		}
		lines[i] = pad + line
	}
	return lines
}

// 按寬度硬切換行（ANSI 安全）。
// 不用 wordwrap：它會在 `-` 斷行，session id 這類長值會被切成只剩一小段的孤行。
func hardWrap(text string, width int) string {
	return wrap.String(text, width)
}

// 把 slog TextHandler 的一行（time=... level=... msg=... k=v ...）解析成 logEntry。
// 第一個欄位不是 time，或不是合法的 logfmt，就當成原始行。
// 只取第一個 level / msg，之後同名的 key 視為一般欄位保留。
func parseLogLine(line string) logEntry {
	pairs, ok := parseLogfmt(line)
	if !ok || len(pairs) == 0 || pairs[0].key != "time" {
		return logEntry{raw: line}
	}

	entry := logEntry{time: pairs[0].value}
	if ts, err := time.Parse(time.RFC3339Nano, pairs[0].value); err == nil {
		entry.time = ts.Local().Format(LOG_TIME_FORMAT)
	}
	for _, pair := range pairs[1:] {
		switch {
		case pair.key == "level" && entry.level == "":
			entry.level = pair.value
		case pair.key == "msg" && entry.msg == "":
			entry.msg = pair.value
		default:
			entry.attrs = append(entry.attrs, pair)
		}
	}
	return entry
}

// 解析 logfmt：以空白分隔的 key=value，value 可用雙引號包住（支援 \" 等跳脫）。
// key 為空、key 含空白或引號、引號未閉合、跳脫字元不合法時回傳 false。
func parseLogfmt(line string) ([]logAttr, bool) {
	var pairs []logAttr
	rest := strings.TrimSpace(line)
	for rest != "" {
		eq := strings.IndexByte(rest, '=')
		if eq <= 0 || strings.ContainsAny(rest[:eq], " \t\"") {
			return nil, false
		}
		key := rest[:eq]
		rest = rest[eq+1:]

		var value string
		if strings.HasPrefix(rest, `"`) {
			// NOTE: 找對應的結尾引號，跳過被反斜線跳脫的字元
			end := 1
			for end < len(rest) && rest[end] != '"' {
				if rest[end] == '\\' {
					end++
				}
				end++
			}
			if end >= len(rest) {
				return nil, false
			}
			unquoted, err := strconv.Unquote(rest[:end+1])
			if err != nil {
				return nil, false
			}
			value = unquoted
			rest = rest[end+1:]
		} else {
			value, rest, _ = strings.Cut(rest, " ")
		}
		pairs = append(pairs, logAttr{key: key, value: value})
		rest = strings.TrimLeft(rest, " ")
	}
	return pairs, true
}

// 監看 daemon.log 並把新增的內容串流回 TUI，直到 ctx 被取消。
// 先讀檔尾一次（即使沒有內容也送出，讓 popup 從 loading 換成空狀態），
// 之後檔案一有變動就讀新增的部分；另每秒輪詢一次，補 fsnotify 漏掉的事件。
func watchDaemonLog(ctx context.Context, target *Popup) {
	path := filesystem.DaemonLogPath
	// NOTE: offset 為已讀到的位元組位置；-1 代表尚未讀過，第一次只讀檔尾
	offset := int64(-1)
	push := func(first bool) {
		lines, next, reset := readLogChunk(path, offset)
		offset = next
		if first || reset || len(lines) > 0 {
			send(LogStream{target: target, lines: lines, reset: reset})
		}
	}
	push(true)

	w, err := fsnotify.NewWatcher()
	if err != nil {
		slog.Warn("log watcher", slog.String("error", err.Error()))
		return
	}
	defer w.Close()
	// NOTE: 監看所在目錄而非檔案本身，檔案被刪除重建或輪替後仍收得到事件
	if err := w.Add(filepath.Dir(path)); err != nil {
		slog.Warn("log watch dir", slog.String("error", err.Error()))
		return
	}

	poll := time.NewTicker(time.Second)
	defer poll.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case ev, ok := <-w.Events:
			if !ok {
				return
			}
			if filepath.Base(ev.Name) == filepath.Base(path) {
				push(false)
			}
		case _, ok := <-w.Errors:
			if !ok {
				return
			}
		case <-poll.C:
			push(false)
		}
	}
}

// 從 offset 讀到檔尾，回傳完整的行與下一次的 offset。
// offset < 0（第一次讀）或檔案比 offset 小（被截斷、輪替）時，改從檔尾 LOG_TAIL_BYTES 開始讀；
// 後者回傳 reset=true，讓畫面清空重建。
// 最後一行若還沒寫完（沒有換行）不讀，留到下次；next 只前進到最後一個換行之後。
func readLogChunk(path string, offset int64) (lines []string, next int64, reset bool) {
	info, err := os.Stat(path)
	// NOTE: 檔案不存在：先前讀過內容代表被移除，要求清空畫面
	if err != nil {
		return nil, 0, offset > 0
	}
	size := info.Size()

	start := offset
	if offset < 0 || size < offset {
		reset = offset > 0
		start = max(size-LOG_TAIL_BYTES, 0)
	}
	if size == start {
		return nil, start, reset
	}

	file, err := os.Open(path)
	if err != nil {
		return nil, max(offset, 0), false
	}
	defer file.Close()
	if _, err := file.Seek(start, io.SeekStart); err != nil {
		return nil, max(offset, 0), false
	}
	raw, err := io.ReadAll(io.LimitReader(file, size-start))
	if err != nil {
		return nil, max(offset, 0), false
	}

	end := bytes.LastIndexByte(raw, '\n')
	if end < 0 {
		return nil, start, reset
	}
	chunk := raw[:end]
	// NOTE: 從檔案中間開始讀時，第一行通常是被切斷的半行，丟棄
	if (offset < 0 || reset) && start > 0 {
		if cut := bytes.IndexByte(chunk, '\n'); cut >= 0 {
			chunk = chunk[cut+1:]
		} else {
			chunk = nil
		}
	}
	for line := range strings.SplitSeq(string(chunk), "\n") {
		if strings.TrimSpace(line) != "" {
			lines = append(lines, line)
		}
	}
	return lines, start + int64(end) + 1, reset
}
